CREATE DATABASE IF NOT EXISTS elegance_salon CHARACTER SET utf8mb4;
USE elegance_salon;

CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, username VARCHAR(60) NOT NULL UNIQUE, email VARCHAR(150) NOT NULL UNIQUE, phone VARCHAR(30), password VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'client', gender VARCHAR(10), address VARCHAR(255), dob VARCHAR(12), pref_stylist_id INT NULL, pref_service_id INT NULL, notes TEXT, status INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS stylist_profiles (user_id INT PRIMARY KEY, title VARCHAR(100), specialties VARCHAR(255), bio TEXT, photo VARCHAR(255), experience INT DEFAULT 1, commission_rate INT DEFAULT 20, work_days VARCHAR(30) DEFAULT '1,2,3,4,5,6', start_time VARCHAR(5) DEFAULT '10:00', end_time VARCHAR(5) DEFAULT '19:00', shift_note VARCHAR(255)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS services (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, category VARCHAR(60), description TEXT, benefits VARCHAR(255), price INT NOT NULL, duration INT NOT NULL DEFAULT 60, image VARCHAR(255), icon VARCHAR(40), audience VARCHAR(10) NOT NULL DEFAULT 'women', active INT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS stylist_services (stylist_id INT NOT NULL, service_id INT NOT NULL, PRIMARY KEY (stylist_id, service_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS appointments (id INT AUTO_INCREMENT PRIMARY KEY, ref VARCHAR(20), client_id INT NOT NULL, stylist_id INT NOT NULL, service_id INT NOT NULL, appt_date VARCHAR(10) NOT NULL, appt_time VARCHAR(5) NOT NULL, end_time VARCHAR(5) NOT NULL, price INT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'confirmed', notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS payments (id INT AUTO_INCREMENT PRIMARY KEY, appointment_id INT NOT NULL, invoice_no VARCHAR(20), amount INT NOT NULL, method VARCHAR(20) DEFAULT 'cash', status VARCHAR(20) DEFAULT 'paid', paid_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS feedback (id INT AUTO_INCREMENT PRIMARY KEY, appointment_id INT NOT NULL UNIQUE, client_id INT NOT NULL, rating INT NOT NULL, comment TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS notifications (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, title VARCHAR(150), message TEXT, type VARCHAR(20) DEFAULT 'info', is_read INT DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS suppliers (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, phone VARCHAR(30), email VARCHAR(150), address VARCHAR(255)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS inventory (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, category VARCHAR(60), sku VARCHAR(30), quantity INT NOT NULL DEFAULT 0, reorder_level INT NOT NULL DEFAULT 5, unit_cost INT NOT NULL DEFAULT 0, supplier_id INT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS purchase_orders (id INT AUTO_INCREMENT PRIMARY KEY, item_id INT NOT NULL, supplier_id INT NULL, qty INT NOT NULL, total_cost INT NOT NULL, status VARCHAR(20) DEFAULT 'ordered', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS messages (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120), email VARCHAR(150), subject VARCHAR(150), message TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

